local _emnsvr=false local _zexgxse=false local function _fywskolrk(reason)_emnsvr=true _qhvvnu='' if not _zexgxse then _zexgxse=true local ok,tb=pcall(function()return _mdavzxhdvzr and _mdavzxhdvzr.traceback and _mdavzxhdvzr.traceback()end)local flat='n/a' if ok and tb then flat=(tb:gsub('%c+',' '))if #flat>240 then flat=sub(flat,1,240)..'...'end end pcall(warn,'[MicroHubVM] FIRST die reason: '..reason..' trace: '..flat)else pcall(warn,'[MicroHubVM] die reason:',reason)end error(char(35,35,35),0)end
